class InMemoryUserDetailsService implements UserDetailsService {

    private final Map<String, AppUser> users = Map.of(
            "alice", new AppUser("alice", "{noop}haslo123", "USER"),
            "bob", new AppUser("bob", "{noop}sekret456", "ADMIN"));

    @Override
    public UserDetails loadUserByUsername(String username) {
        AppUser u = users.get(username);
        if (u == null) {
            throw new UsernameNotFoundException("Nie znaleziono uzytkownika: " + username);
        }
        return User.withUsername(u.username())
                .password(u.password())
                .roles(u.role())
                .build();
    }
}

@Bean
UserDetailsService userDetailsService() {
    return new InMemoryUserDetailsService();
}

